export function FormSelectField({
  label,
  caption,
  required = false,
  value,
  options,
  placeholder = 'Выберите значение',
  disabled = false,
  className,
  selectClassName,
  dropdownClassName,
  onValueChange,
}: FormSelectFieldProps) {
  const listboxId = useId();
  const rootRef = useRef<HTMLDivElement | null>(null);
  const [isOpen, setIsOpen] = useState(false);

  const selectedOption = options.find((option) => option.value === value);

  useEffect(() => {
    if (!isOpen) {
      return;
    }

    function handleDocumentMouseDown(event: MouseEvent) {
      if (!rootRef.current?.contains(event.target as Node)) {
        setIsOpen(false);
      }
    }

    document.addEventListener('mousedown', handleDocumentMouseDown);

    return () => {
      document.removeEventListener('mousedown', handleDocumentMouseDown);
    };
  }, [isOpen]);

  function handleTriggerKeyDown(event: KeyboardEvent<HTMLButtonElement>) {
    if (event.key === 'Escape') {
      setIsOpen(false);
      return;
    }

    if (event.key === 'Enter' || event.key === ' ') {
      event.preventDefault();
      setIsOpen((currentValue) => !currentValue);
    }
  }

  function handleOptionClick(option: FormSelectOption) {
    if (option.disabled) {
      return;
    }

    onValueChange(option.value);
    setIsOpen(false);
  }

  return (
    <FormFieldRoot
      label={label}
      caption={caption}
      required={required}
      className={className}
    >
      <div ref={rootRef} className="relative">
        <button
          type="button"
          disabled={disabled}
          aria-haspopup="listbox"
          aria-expanded={isOpen}
          aria-controls={listboxId}
          aria-required={required}
          className={cn(SELECT_TRIGGER_CLASS_NAME, selectClassName)}
          onClick={() => setIsOpen((currentValue) => !currentValue)}
          onKeyDown={handleTriggerKeyDown}
        >
          <span
            className={cn(
              'truncate',
              !selectedOption && 'text-muted-foreground',
            )}
          >
            {selectedOption?.label ?? placeholder}
          </span>

          <ChevronDown
            className={cn(
              'size-4 shrink-0 text-muted-foreground transition-transform',
              isOpen && 'rotate-180',
            )}
            strokeWidth={1.5}
          />
        </button>

        {isOpen && (
          <div
            id={listboxId}
            role="listbox"
            className={cn(
              'absolute left-0 right-0 top-full z-30 mt-2 max-h-64 overflow-y-auto rounded-lg border border-border bg-popover p-1 text-sm shadow-lg',
              dropdownClassName,
            )}
          >
            {options.map((option) => {
              const isSelected = option.value === value;

              return (
                <button
                  key={option.value}
                  type="button"
                  role="option"
                  aria-selected={isSelected}
                  disabled={option.disabled}
                  className={cn(
                    'flex w-full cursor-pointer items-center justify-between gap-3 rounded-md px-3 py-2 text-left transition-colors',
                    'hover:bg-muted hover:text-foreground',
                    'disabled:cursor-not-allowed disabled:opacity-50',
                    isSelected && 'bg-muted text-foreground',
                  )}
                  onClick={() => handleOptionClick(option)}
                >
                  <span className="truncate">{option.label}</span>

                  {isSelected && (
                    <Check className="size-4 shrink-0" strokeWidth={1.5} />
                  )}
                </button>
              );
            })}

