  'w-full resize-none rounded-lg border border-border bg-background px-3 py-2 text-sm leading-5 outline-none transition-colors placeholder:text-muted-foreground focus:border-ring focus:ring-3 focus:ring-ring/50 disabled:cursor-not-allowed disabled:opacity-50';

const SELECT_TRIGGER_CLASS_NAME =
  'flex h-10 w-full cursor-pointer items-center justify-between gap-3 rounded-lg border border-border bg-background px-3 py-2 text-left text-sm outline-none transition-colors hover:border-ring focus-visible:border-ring focus-visible:ring-3 focus-visible:ring-ring/50 disabled:cursor-not-allowed disabled:opacity-50';

const FILE_DROPZONE_CLASS_NAME =
  'flex min-h-32 cursor-pointer flex-col items-center justify-center rounded-xl border border-dashed border-border bg-muted/30 px-4 py-5 text-center transition-colors hover:border-ring hover:bg-muted/50';

function FormFieldRoot({
  label,
  caption,
  required = false,
  className,
  children,
}: FormFieldRootProps) {
  return (
    <div className={cn('flex flex-col', className)}>
      <span
        className={cn(
          'mb-2 ml-0.5 text-sm font-medium',
          required &&
          "after:ml-1 after:text-destructive after:content-['*']",
        )}
      >
        {label}
      </span>

      {children}

      {caption && (
        <span className="mt-1 ml-0.5 text-xs leading-5 text-muted-foreground">
          {caption}
        </span>
      )}
    </div>
  );
}

function formatFileSize(size: number) {
  if (size < 1024 * 1024) {
    return `${Math.max(1, Math.round(size / 1024))} КБ`;
  }

  return `${(size / 1024 / 1024).toFixed(1)} МБ`;
}

export function FormInputField({
  name,
  label,
  caption,
  required = false,
  value,
  placeholder,
  type = 'text',
  inputMode,
  disabled = false,
  minLength,
  autoComplete = 'off',
  className,
  inputClassName,
  onChange,
}: FormInputFieldProps) {
  return (
    <FormFieldRoot
      label={label}
      caption={caption}
      required={required}
      className={className}
    >
      <Input
        name={name}
        required={required}
        disabled={disabled}
        type={type}
        inputMode={inputMode}
        value={value}
        minLength={minLength}
        autoComplete={autoComplete}
        placeholder={placeholder}
        className={inputClassName}
        onChange={onChange}
      />
    </FormFieldRoot>
  );
}

export function FormTextareaField({
  name,
  label,
  caption,
  required = false,
  value,
  placeholder,
  rows = 4,
  disabled = false,
  className,
  textareaClassName,
  onChange,
}: FormTextareaFieldProps) {
  return (
    <FormFieldRoot
                </Button>
                <div className="flex">
                  <Button type="button" size="icon" variant="ghost" disabled={index === 0}
                    onClick={() => move(index, -1)} aria-label="Переместить вверх">
                    <ArrowUp className="size-4" />
                  </Button>
                  <Button type="button" size="icon" variant="ghost" disabled={index === value.length - 1}
                    onClick={() => move(index, 1)} aria-label="Переместить вниз">
                    <ArrowDown className="size-4" />
                  </Button>
                </div>
                <Button type="button" size="icon" variant="ghost"
                  onClick={() => removeAddition(index, addition.id)}
                  aria-label="Удалить дополнение">
                  <X className="size-4" />
                </Button>
              </div>
            </div>

            {visibleAdditionId === addition.id && <div className="space-y-3">
              <label className="block space-y-1 text-sm">
                <span>Заголовок</span>
                <input required className="w-full rounded-md border border-input bg-background px-3 py-2"
                  value={addition.title}
                  onChange={(event) => update(index, { ...addition, title: event.target.value })} />
              </label>
              <label className="block space-y-1 text-sm">
                <span>{addition.type === 'quantity' ? 'Цена за единицу' : 'Цена'}</span>
                <input required type="number" min={0} step={1}
                  className="w-full rounded-md border border-input bg-background px-3 py-2"
                  value={addition.price}
                  onChange={(event) => update(index, { ...addition, price: Number(event.target.value) })} />
              </label>
              <FormBooleanField
                label="Обязательное дополнение"
                variant="toggle"
                checked={addition.required}
                onCheckedChange={(required) => {
                  update(index, addition.type === 'quantity'
                    ? { ...addition, required, min: required ? Math.max(1, addition.min) : addition.min }
                    : { ...addition, required });
                }}
              />

              {addition.type === 'boolean' ? (
                <FormSelectField
                  label="Значение по умолчанию"
                  value={
                    addition.defaultValue === null
                      ? ''
                      : String(addition.defaultValue)
                  }
                  options={[
                    { value: '', label: 'Не задано' },
                    { value: 'true', label: 'Да' },
                    { value: 'false', label: 'Нет' },
                  ]}
                  onValueChange={(nextValue) =>
                    update(index, {
                      ...addition,
                      defaultValue:
                        nextValue === '' ? null : nextValue === 'true',
                    })
                  }
                />
              ) : (
                <div className="grid gap-3 sm:grid-cols-2">
                  <label className="space-y-1 text-sm"><span>Обозначение единицы</span>
                    <input required className="w-full rounded-md border border-input bg-background px-3 py-2"
                      value={addition.unitLabel}
                      onChange={(event) => update(index, { ...addition, unitLabel: event.target.value })} />
                  </label>
                  <label className="space-y-1 text-sm"><span>Минимум</span>
                    <input required type="number" min={addition.required ? 1 : 0} step={1}
                      className="w-full rounded-md border border-input bg-background px-3 py-2"
                      value={addition.min}
                      onChange={(event) => update(index, { ...addition, min: Number(event.target.value) })} />
                  </label>
                  <label className="space-y-1 text-sm"><span>Максимум</span>
                    <input type="number" min={addition.min} step={1}
                      className="w-full rounded-md border border-input bg-background px-3 py-2"
                      value={addition.max ?? ''}
                      onChange={(event) => update(index, {
                        ...addition,
                        max: event.target.value === '' ? null : Number(event.target.value),
                      })} />
                  </label>
                  <label className="space-y-1 text-sm"><span>По умолчанию</span>
                    <input type="number" min={addition.min} max={addition.max ?? undefined} step={1}
                      className="w-full rounded-md border border-input bg-background px-3 py-2"
                      value={addition.defaultValue ?? ''}
                      onChange={(event) => update(index, {
                        ...addition,
                        defaultValue: event.target.value === '' ? null : Number(event.target.value),
                      })} />
                  </label>
                </div>
              )}
            </div>}
          </div>
        ))}

        {isError && <p className="text-sm text-destructive">Не удалось загрузить типы дополнений.</p>}
      </div>

      <div className="space-y-2">
        <p className="text-sm">Добавить тип дополнения:</p>
        <div className="flex flex-wrap gap-2">
          {types.map((type) => (
            <Button
              key={type.key}
              type="button"
              variant="ghost"
              size="sm"
              className="rounded-full border border-border bg-muted/60 px-3 text-xs hover:bg-muted"
              onClick={() => addAddition(type.key)}
            >
              {type.name}
            </Button>
          ))}
        </div>
      </div>
    </section>
  );
}

